-- ============================================================================
-- Migration 006: Carr Landscape Depot 2026 material price list
-- ============================================================================
-- Loads Golden Maple's supplier price book (Carr Landscape Depot, Barrie ON)
-- into a queryable material_prices catalog so it can be used when building
-- quotes. Source: "2026 Complete Price List V1" (printed 2026-05-27), 853
-- items across bulk aggregate/soil/mulch, slabs & pavers, porcelain tile,
-- and natural stone. Listed prices are TRADE prices (the bulk section also
-- shows retail); prices exclude HST and delivery is extra.
--
-- price_raw / trade_price_raw keep the exact printed value (incl. cents like
-- ".063¢" and "N/A"); price_cad / trade_price_cad are the parsed dollar
-- amounts (NULL when the printed value is not a plain dollar figure).
-- Re-running this migration replaces the existing Carr list for the contractor.
-- ============================================================================

CREATE TABLE IF NOT EXISTS material_prices (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  contractor_id UUID NOT NULL REFERENCES contractors(id) ON DELETE CASCADE,
  supplier TEXT NOT NULL,
  price_list_version TEXT,
  effective_date DATE,
  category TEXT,
  product_group TEXT,
  name TEXT,
  variant TEXT,
  description TEXT,
  item_code TEXT,
  dimensions TEXT,
  unit TEXT,
  skid_size TEXT,
  price_raw TEXT,
  price_cad NUMERIC,
  trade_price_raw TEXT,
  trade_price_cad NUMERIC,
  unit_price TEXT,
  splitting_fee TEXT,
  delivery TEXT,
  source_page INTEGER,
  raw TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_material_prices_contractor
  ON material_prices(contractor_id);
CREATE INDEX IF NOT EXISTS idx_material_prices_lookup
  ON material_prices(contractor_id, supplier, category);

ALTER TABLE material_prices ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
  CREATE POLICY "material_prices_own_data" ON material_prices
    FOR ALL USING (contractor_id = auth.uid());
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE POLICY "public_material_prices" ON material_prices
    FOR SELECT USING (
      contractor_id IN (
        SELECT id FROM contractors WHERE plan_status IN ('active', 'trialing')
      )
    );
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

